"""OpenAI Responses API client using only Python 3 standard library."""
import json
import urllib.request
import urllib.error


DEFAULT_URL = "https://api.openai.com/v1/responses"


class OpenAIClient:
    """Send private text prompts to OpenAI's Responses API."""

    def __init__(self, api_key: str, url: str = DEFAULT_URL):
        self.api_key = api_key
        self.url = url

    def send(self, prompt: str, model: str = "gpt-4o") -> dict:
        payload = json.dumps({
            "model": model,
            "input": prompt,
        }).encode("utf-8")
        req = urllib.request.Request(
            self.url,
            data=payload,
            headers={
                "Authorization": f"Bearer {self.api_key}",
                "Content-Type": "application/json",
            },
            method="POST",
        )
        with urllib.request.urlopen(req) as resp:
            return json.loads(resp.read().decode("utf-8"))
